    {
      "service": "ts-train-service",
      "fault_kind": "application_exception",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, attr_http_response_status_code AS code, count(*) AS n, round(quantile_cont(duration,0.5)/1e6,1) AS p50_ms FROM abnormal_traces WHERE service_name='ts-train-service' AND attr_span_kind='Server' GROUP BY 1,2,3 ORDER BY n DESC",
          "claim": "Train server spans fail with HTTP 500 on nearly all byName requests, answering in about 2.5 ms p50."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, count(*) AS n FROM abnormal_logs WHERE service_name='ts-train-service' AND level='SEVERE' AND message LIKE '%NullPointerException%' GROUP BY 1,2",
          "claim": "ts-train-service logs about 1981 SEVERE dispatcher exceptions wrapping java.lang.NullPointerException in the abnormal window."
        },
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller, s.service_name AS callee, s.attr_http_response_status_code AS code, count(*) AS n, round(quantile_cont(p.duration,0.5)/1e6,1) AS caller_p50_ms FROM abnormal_traces s JOIN abnormal_traces p ON s.parent_span_id=p.span_id AND s.trace_id=p.trace_id WHERE s.service_name='ts-train-service' AND s.attr_span_kind='Server' AND s.span_name LIKE '%byName%' GROUP BY 1,2,3",
          "claim": "Callers basic-service and travel-plan-service get 500s from train's byName endpoint after about 3.5 s each."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-train-service",
      "to": "ts-basic-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller, s.service_name AS callee, s.attr_http_response_status_code AS code, count(*) AS n FROM abnormal_traces s JOIN abnormal_traces p ON s.parent_span_id=p.span_id AND s.trace_id=p.trace_id WHERE s.service_name='ts-train-service' AND s.attr_span_kind='Server' AND p.service_name='ts-basic-service' GROUP BY 1,2,3",
          "claim": "basic-service's GET calls to train return 500 in about 1,400 cases in the abnormal window."
        }
      ]
    },
    {
      "from": "ts-basic-service",
      "to": "ts-travel-service",
